const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point(-79.198692, 43.244129);
  const point2 = ee.Geometry.Point(-79.069485, 43.263113);
  const date = '2021-02-04';
  const buffer_radius = 100; // Use a small buffer to get a mean around the point
  const scale = 10; // Sentinel-2 resolution is 10m for B4, B8

  // Function to mask clouds in Sentinel-2 images
  function maskS2clouds(image) {
    const qa = image.select('QA60');

    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;

    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    // Also mask out pixels where the SCL band indicates cloud/shadow/snow/ice
    // SCL values: 3=cloud shadow, 8=cloud medium probability, 9=cloud high probability, 10=cirrus, 11=snow/ice
    const scl = image.select('SCL');
    const cloudShadowSnowMask = scl.eq(3).or(scl.eq(8)).or(scl.eq(9)).or(scl.eq(10)).or(scl.eq(11)).not();

    return image.updateMask(mask).updateMask(cloudShadowSnowMask).divide(10000); // Scale to SR
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(point1.union(point2))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)); // Initial cloud filter

  // Check if collection is empty
  const initial_size = await collection.size().getInfo();
  if (initial_size === 0) {
    console.log("No Sentinel-2 images found for 2021-02-04. Trying Landsat 8 SR.");
    // Fallback to Landsat 8 SR
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(point1.union(point2))
      .filter(ee.Filter.lt('CLOUD_COVER', 80)); // Landsat 8 cloud filter

    const ls8_size = await collection.size().getInfo();
    if (ls8_size === 0) {
      console.log("No Landsat 8 images found either.");
      console.log("C1");
      return;
    }

    // Landsat 8 specific processing
    function maskL8clouds(image) {
      const qa = image.select('QA_PIXEL');
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 3);
      const cloudBitMask = (1 << 5);
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudBitMask).eq(0));
      return image.updateMask(mask).divide(10000); // Scale to SR
    }
    function addL8NDVI(image) {
      const ndvi = image.normalizedDifference(['B5', 'B4']).rename('NDVI'); // L8: B5=NIR, B4=Red
      return image.addBands(ndvi);
    }
    collection = collection.map(maskL8clouds).map(addL8NDVI);
    console.log(`Landsat 8 images found: ${ls8_size}`);
  } else {
    // Sentinel-2 processing
    collection = collection.map(maskS2clouds).map(addNDVI);
    console.log(`Sentinel-2 images found: ${initial_size}`);
  }

  const image = collection.median(); // Use median to combine multiple images, if any

  // 3. Processing & Calculation
  // Check if the median image is null or has no bands (after masking)
  const bandNames = await image.bandNames().getInfo();
  if (!bandNames || bandNames.indexOf('NDVI') === -1) {
    console.log("Image processing failed or NDVI band not found.");
    console.log("C3");
    return;
  }

  const getNDVI = async (geometry, name) => {
    const reducer = ee.Reducer.count().combine({
      reducer2: ee.Reducer.mean(),
      sharedInputs: true
    });

    const stats = await image.reduceRegion({
      reducer: reducer,
      geometry: geometry.buffer(buffer_radius),
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const pixel_count = stats.NDVI_count;
    const ndvi_value = stats.NDVI_mean;

    if (pixel_count === 0) {
      console.log(`No valid pixels found for ${name} after masking.`);
      return { ndvi: null, pixels: 0 };
    }

    if (ndvi_value === null || isNaN(ndvi_value) || ndvi_value < -1 || ndvi_value > 1) {
      console.log(`NDVI calculation failed for ${name}: ${ndvi_value}`);
      return { ndvi: null, pixels: pixel_count };
    }
    return { ndvi: ndvi_value, pixels: pixel_count };
  };

  const result1 = await getNDVI(point1, 'Point 1');
  const result2 = await getNDVI(point2, 'Point 2');

  if (result1.pixels === 0 || result2.pixels === 0) {
    console.log("C2"); // One or both points had no valid pixels after masking
    return;
  }

  if (result1.ndvi === null || result2.ndvi === null) {
    console.log("C3"); // Calculation failure (e.g., NaN, null)
    return;
  }

  console.log(`Point 1 (43.244129, -79.198692) NDVI: ${result1.ndvi.toFixed(4)}, Pixels: ${result1.pixels}`);
  console.log(`Point 2 (43.263113, -79.069485) NDVI: ${result2.ndvi.toFixed(4)}, Pixels: ${result2.pixels}`);

  // 5. Validation & Final Answer
  if (result1.ndvi > result2.ndvi) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
